-- The Costs tab on /admin (lib/costs.js): one JSON snapshot per row, the newest 30 kept. Safe to apply twice: the table is
-- created if missing and the first snapshot (2026-10-16, from the Operations session) goes in only while the table is empty.
-- Apply: npx wrangler d1 execute <DB name> --remote --file site/migrations/cost-snapshots.sql
-- (The Function also creates the table itself, so POSTing a snapshot works without this; the seed is what this adds.)

CREATE TABLE IF NOT EXISTS cost_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, taken_at TEXT NOT NULL, json TEXT NOT NULL);

